"""Original neurological examination questions: motor, sensory and coordination localization."""
from qbank_authoring import question,ref
rows=[]
NE=ref('Clinical Methods: neurological examination overview','https://www.ncbi.nlm.nih.gov/books/NBK373/')
RE=ref('Clinical Methods: deep tendon reflexes','https://www.ncbi.nlm.nih.gov/books/NBK396/')
UT=ref('University of Utah NeuroLogic examination: motor assessment','https://neurologicexam.med.utah.edu/adult/html/motor_normal.html')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('Weakness is accompanied by velocity-dependent hypertonia, brisk reflexes and an extensor plantar response. Which localization is most strongly supported?', 'An upper motor neuron/corticospinal-system lesion',[
 ('A pure distal peripheral axonal neuropathy','That more often reduces reflexes and tone in affected regions.'),('A pure neuromuscular-junction disorder','This usually does not produce the described pyramidal signs.'),('An isolated primary myopathy','The pattern is not the typical pure muscle syndrome.')],
 'Use the pattern rather than weakness alone','**Tone, reflexes, plantar responses and distribution refine motor localization.**',['Central lesions can coexist with peripheral disease.','The examination does not establish the exact lesion site or cause by itself.'],'**Complete cranial, sensory and gait assessment.**',['Use onset and associated findings to guide urgent imaging or other tests.','Do not infer stroke from a chronic pyramidal pattern alone.'],[['UMN','Spasticity/hyperreflexia/extensor plantar'],['LMN','Atrophy/fasciculation/reduced reflexes'],['Muscle/NMJ','Different associated pattern']],[NE],style='clinical_scenario')

q('A patient has abrupt hemiplegia that is initially flaccid with reduced reflexes. Which statement is correct?', 'An acute central lesion remains possible despite the absence of established spasticity',[
 ('Flaccidity permanently excludes a central lesion','Acute UMN lesions can initially have reduced tone/reflexes.'),('Reduced reflexes prove chronic peripheral neuropathy as the only cause','Time course and distribution argue against that automatic conclusion.'),('Imaging should wait until Babinski and spasticity appear','Urgent onset requires prompt assessment.')],
 'Motor signs evolve over time','**The mature UMN pattern may be absent early.**',['Acute spinal or cerebral injury can produce a transient flaccid state.','Onset and accompanying signs remain critical.'],'**Use the acute-neurological pathway appropriate to the presentation.**',['Check glucose and other immediate mimics.','Repeat the examination without delaying time-sensitive care.'],[['Early central injury','May be flaccid'],['Later','Pyramidal signs can emerge'],['Urgency','Determined by onset and syndrome']],[NE],style='clinical_scenario')

q('With both arms outstretched and palms upward, one arm pronates and drifts downward. Which finding is supported?', 'Subtle corticospinal-pattern weakness on that side',[
 ('A uniquely diagnostic cerebellar lesion','Cerebellar drift may have a different pattern; pronation favors pyramidal weakness.'),('A normal response proving equal power','Asymmetric pronating drift is abnormal in the right context.'),('A direct measurement of sensory nerve conduction','This is a bedside motor-control sign.')],
 'A sustained posture can expose subtle asymmetry','**Pronation and downward drift can reveal weakness not obvious on brief confrontation testing.**',['Pain, effort and proprioceptive problems can confound interpretation.','Compare the full motor examination.'],'**Localize with associated signs.**',['Assess reflexes, face and sensation.','Do not assign etiology from drift alone.'],[['Test','Arms extended/palms up'],['Pyramidal clue','Pronation/downward drift'],['Confirmation','Full motor localization']],[UT],style='clinical_scenario')

q('A patient can move the elbow through full range against gravity but cannot sustain movement against added resistance. What MRC strength grade is appropriate?', '3/5',[
 ('2/5','This describes movement when gravity is eliminated.'),('4/5','This requires movement against resistance, though weaker than normal.'),('5/5','This implies normal strength.')],
 'Grade the tested action under defined mechanical conditions','**Grade three means antigravity movement without added resistance.**',['Pain and limited joint range can make grading misleading.','Document the muscle/action and side rather than only a global limb score.'],'**Interpret weakness distribution with the rest of the examination.**',['Use reproducible positioning.','Do not equate a score with a specific diagnosis.'],[['2','Gravity eliminated'],['3','Against gravity'],['4','Against resistance but weak']],[UT])

q('An ankle reflex is difficult to obtain in a tense patient. What is the best next technique before calling it absent?', 'Ensure relaxation and positioning, then use reinforcement when appropriate',[
 ('Strike progressively harder without positioning review','Technique and relaxation matter more than indiscriminate force.'),('Record complete neuropathy from one uncertain reflex','A single finding is insufficient.'),('Assume all absent ankle reflexes are pathological at every age','Age and clinical context affect interpretation.')],
 'A reflex test includes the examiner’s technique','**The tendon, muscle position and relaxation determine the elicited response.**',['Compare sides and use reinforcement judiciously.','Peripheral and central disorders can coexist.'],'**Interpret the distribution rather than a lone result.**',['Assess sensation, strength and other reflexes.','Document uncertainty and repeat when necessary.'],[['Technique','Relaxation/position'],['Comparison','Side and regional pattern'],['Interpretation','Clinical context']],[RE])

q('Sustained ankle clonus with other pyramidal signs most strongly supports which process?', 'An abnormally excitable stretch-reflex system associated with an UMN lesion',[
 ('A pure motor-endplate transmission failure','That does not usually produce sustained clonus.'),('A distal axonal neuropathy as the sole explanation','Peripheral axonal loss more often reduces the reflex.'),('Normal strength and tone are guaranteed because the movement is rhythmic','Rhythmicity does not make the response physiological.')],
 'Clonus is an oscillating stretch-reflex response','**Sustained clonus is interpreted with tone, reflexes and plantar responses.**',['Brief responses can have different significance depending on context.','Drugs and systemic states can alter reflex excitability.'],'**Complete localization and assess the cause.**',['Do not diagnose a specific spinal level from ankle clonus alone.','Use the distribution and sensory findings.'],[['Clonus','Repetitive stretch response'],['Associated pattern','UMN signs'],['Etiology','Requires further assessment']],[RE])

q('In an adult, slow extension of the great toe with appropriate plantar stimulation is observed. Which interpretation is appropriate?', 'An extensor plantar response supporting corticospinal dysfunction in context',[
 ('It is equivalent to any brisk withdrawal of the whole foot','Withdrawal and a true extensor plantar response must be distinguished.'),('It uniquely identifies a peripheral peroneal neuropathy','That does not account for the corticospinal sign.'),('It localizes the lesion precisely to the motor cortex','The corticospinal pathway can be affected at several levels.')],
 'Observe the toe response rather than merely the leg movement','**Technique and distinction from withdrawal matter.**',['Avoid excessive painful stimulation.','The finding can be equivocal and should be documented as such when necessary.'],'**Integrate with strength, tone, reflexes and sensation.**',['Use the broader pattern for brain versus cord localization.','Do not infer a specific cause from the sign alone.'],[['Response','Great-toe extension'],['Pathway','Corticospinal'],['Limit','Not exact site/etiology']],[NE])

q('Distal loss of vibration and pin sensation is symmetrical, begins in the feet and advances in a stocking pattern, with reduced ankle reflexes. Which localization is favored?', 'Length-dependent peripheral polyneuropathy',[
 ('A single lumbosacral root lesion','A root lesion usually follows a more focal myotomal/dermatomal pattern.'),('A thoracic spinal sensory level','That has a truncal level rather than this distal length-dependent pattern.'),('A unilateral cortical sensory lesion','That more often causes a hemisensory/cortical pattern.')],
 'Distribution is a major localization tool','**Long axons are often affected first in length-dependent neuropathy.**',['Motor and autonomic involvement can add clues.','The pattern does not identify a single cause.'],'**Investigate metabolic, nutritional, toxic and other etiologies.**',['Assess gait, foot protection and falls.','Use electrodiagnostics when the clinical question warrants them.'],[['Pattern','Distal symmetric'],['Reflexes','Often reduced distally'],['Localization','Peripheral nerves']],[NE],style='clinical_scenario')

q('Which combination favors a nerve-root lesion over a single peripheral-nerve lesion?', 'Weakness across different nerves sharing a myotome with a compatible dermatomal sensory/reflex pattern',[
 ('Deficits confined to one named nerve territory','This more strongly supports a mononeuropathy.'),('Symmetrical stocking sensory loss','This favors polyneuropathy.'),('A homonymous visual field defect','This indicates a retrochiasmal central process.')],
 'Roots and nerves organize deficits differently','**A root supplies muscles distributed through more than one peripheral nerve.**',['Dermatomes overlap and sensory findings can be subtle.','Pain and reflex changes provide supporting information.'],'**Map muscles individually and correlate with the history.**',['Use imaging/electrodiagnostics to answer specific uncertainty.','Avoid localizing from one painful muscle test alone.'],[['Root','Myotomal across nerves'],['Nerve','Named nerve distribution'],['Interpretation','Combined motor/sensory/reflex map']],[NE])

q('A patient has bilateral leg weakness, brisk reflexes and a clear truncal sensory level. Which localization is most concerning?', 'Spinal cord disease',[
 ('A length-dependent peripheral neuropathy alone','This does not usually produce a truncal level with pyramidal signs.'),('An isolated neuromuscular-junction disorder','It does not cause a sensory level.'),('A primary muscle disorder','This also does not explain the sensory level.')],
 'A sensory level can be a key cord clue','**Motor and sensory findings together support myelopathy.**',['The clinical level can differ from the exact structural level.','Bladder/bowel symptoms and saddle findings add urgency.'],'**Arrange urgent cause-directed spinal assessment when onset or progression warrants it.**',['Consider compression, inflammation and vascular causes.','Do not delay because the arms are normal.'],[['Motor','Possible UMN legs'],['Sensory','Truncal level'],['Localization','Cord']],[NE],style='clinical_scenario')

q('A patient stands steadily with eyes open but loses balance when the eyes close, with impaired joint-position sense. Which mechanism is favored?', 'Sensory ataxia from impaired proprioceptive input',[
 ('A purely cerebellar ataxia as the only explanation','Cerebellar instability is often evident even with eyes open.'),('A normal Romberg response','Marked loss of balance is abnormal.'),('A diagnosis of peripheral vestibular disease uniquely established by the test','Vestibular input also matters, but the proprioceptive deficit points to sensory ataxia.')],
 'Vision can compensate for lost position information','**Closing the eyes removes that compensation.**',['Dorsal-column or large-fiber peripheral disease can produce the pattern.','Romberg is not simply a generic cerebellar test.'],'**Localize the sensory deficit further.**',['Assess vibration, reflexes and sensory distribution.','Guard the patient to prevent a fall.'],[['Eyes open','Visual compensation'],['Eyes closed','Balance worsens'],['Cause','Proprioceptive pathway assessment']],[NE],style='clinical_scenario')

q('A patient has a broad-based unstable stance even with eyes open, limb dysmetria and scanning dysarthria. Which system is most strongly implicated?', 'Cerebellar circuitry',[
 ('Pure posterior-column sensory loss','Vision often helps compensate and the associated cerebellar signs are less expected.'),('An isolated distal foot-drop neuropathy','This does not explain dysmetria and scanning speech.'),('A pure neuromuscular-junction disorder','This produces weakness/fatigability rather than the described coordination syndrome.')],
 'Coordination signs should agree across tasks','**Dysmetria and speech/gait abnormalities support a cerebellar syndrome.**',['Weakness, sensory loss, intoxication and vestibular disease can complicate testing.','The syndrome does not establish one etiology.'],'**Assess onset, laterality and associated brainstem signs.**',['Acute onset can require urgent vascular evaluation.','Test safely and account for weakness or pain.'],[['Limb','Dysmetria'],['Speech','Scanning/ataxic'],['Gait','Broad-based instability']],[NE],style='clinical_scenario')

q('Impaired rapid alternating movements despite adequate strength and understanding are best described as which sign?', 'Dysdiadochokinesia',[
 ('Aphasia','This concerns language function.'),('Asterixis','This is brief loss of sustained muscle activity.'),('Fasciculation','This is spontaneous motor-unit activity visible in muscle.')],
 'A coordination test requires adequate motor and cognitive prerequisites','**Irregular slow alternating movements can support cerebellar dysfunction.**',['Weakness, pain, bradykinesia and poor comprehension can mimic poor performance.','Compare sides and other coordination tasks.'],'**Use the pattern to refine localization.**',['Do not diagnose a cerebellar lesion from one confounded test.','Assess gait, eye movements and speech.'],[['Task','Rapid alternation'],['Sign','Dysdiadochokinesia'],['Confounders','Weakness/pain/understanding']],[NE])

q('A patient with acute continuous vertigo has direction-changing gaze-evoked nystagmus and severe gait instability. Which concern is most appropriate?', 'A central vestibular cause including posterior circulation stroke',[
 ('A peripheral cause is guaranteed because vertigo is present','Stroke can present with vertigo.'),('Unidirectional or changing nystagmus never needs contextual interpretation','The pattern and full examination matter.'),('Normal limb power excludes a posterior circulation lesion','Posterior circulation disease can spare limb strength.')],
 'Eye movements and gait can reveal a central syndrome','**Direction-changing gaze-evoked nystagmus is a concerning central sign in the appropriate acute setting.**',['Other neurological findings may be subtle.','Use a timing-and-trigger classification and trained bedside assessment.'],'**Escalate for appropriate stroke evaluation.**',['Do not apply HINTS outside its validated syndrome or expertise context.','An early negative test or scan may not settle every posterior-fossa question.'],[['Nystagmus','Central-pattern concern'],['Gait','Severe instability'],['Action','Appropriate urgent evaluation']],[ref('SAEM GRACE-3 acute dizziness guideline','https://www.saem.org/publications/grace/grace-3')],style='clinical_scenario')
